@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const s=document.getElementById('filterState'),d=document.getElementById('filterDistrict'),t=document.getElementById('filterTaluka');const f=()=>{[...d.options].forEach((o,i)=>{if(i)o.hidden=!!s.value&&o.dataset.state!==s.value});if(d.selectedOptions[0]?.hidden)d.value='';[...t.options].forEach((o,i)=>{if(i)o.hidden=!!d.value&&o.dataset.district!==d.value});if(t.selectedOptions[0]?.hidden)t.value=''};s.addEventListener('change',f);d.addEventListener('change',f);f()});</script>@endpush
